  for j,x in enumerate(SS):
   v=cols[x];rel=1<<j
   while v:
    p=v.bit_length()-1
    if p not in bas:bas[p]=(v,rel);break
    a,b=bas[p];v^=a;rel^=b
   if not v:kern.append(rel)
  stats[(w,len(kern))]+=1
  # Exact full-support switch basis embedded in both i-fibers.
